static void unescape_tag(char *tag)
{
        char *tmp;

        if (tag == NULL)
                return;

        tmp = tag;
        for (; *tmp != '\0'; tmp++, tag++) {
                if (*tmp == '\\') {
                        tmp++;
                        switch (*tmp) {
                        case ':':
